from auth0.authentication import AuthenticationAPIClient
from auth0.exceptions import Auth0Error

def pkce_login(payload, config=None):
    config = config or {}
    domain = config.get("AUTH0_DOMAIN", os.environ.get("AUTH0_DOMAIN"))
    client_id = config.get("AUTH0_CLIENT_ID", os.environ.get("AUTH0_CLIENT_ID"))
    redirect_uri = config.get("REDIRECT_URI", os.environ.get("REDIRECT_URI"))

    auth_client = AuthenticationAPIClient(domain=domain)

    code = payload.get("code")
    code_verifier = payload.get("code_verifier")

    token_data = {}
    if all((domain, client_id, redirect_uri, code, code_verifier)):
        try:
            token_data = auth_client.get_token(
                grant_type="authorization_code",
                client_id=client_id,
                client_secret=None,  # PKCE is for public clients that cannot store a secret
                code=code,
                redirect_uri=redirect_uri,
                code_verifier=code_verifier,
            )
        except Auth0Error as e:
            token_data = {"error": "authentication_failed", "error_description": str(e)}
    else:
        token_data = {"error": "invalid_request", "error_description": "Missing required parameters or configuration."}
    result = token_data
    return result
